import sqlite3
con = sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)
print("user_version:", con.execute("PRAGMA user_version").fetchone()[0])
tabs = [t for (t,) in con.execute("select name from sqlite_master where type='table' order by name")]
views = [v for (v,) in con.execute("select name from sqlite_master where type='view' order by name")]
print("tables:", len(tabs), " views:", len(views))
rows = {t: con.execute('select count(*) from "%s"' % t).fetchone()[0] for t in tabs}
print("\n--- NON-EMPTY ---")
for t, n in sorted(rows.items(), key=lambda kv: -kv[1]):
    if n:
        print("%7d  %s" % (n, t))
print("\n--- EMPTY ---")
print("  ".join(t for t, n in sorted(rows.items()) if not n))
empty = {t for t, n in rows.items() if not n}
print("\n--- UNWRITABLE ---")
for t in tabs:
    fks = list(con.execute('PRAGMA foreign_key_list("%s")' % t))
    dead = {f[3]: f[2] for f in fks if f[2] in empty}
    for c in con.execute('PRAGMA table_info("%s")' % t):
        if c[1] in dead and c[3]:
            print("  UNWRITABLE  %s.%s -> %s (empty)" % (t, c[1], dead[c[1]]))
print("\n--- VIEWS ---")
print("  ".join(views))
